const javaPrim = { string:'String', number:'Long', boolean:'Boolean', decimal:'java.math.BigDecimal', date:'java.time.LocalDateTime', uuid:'java.util.UUID' };
const esField = { string:'Text', number:'Long', boolean:'Boolean', decimal:'Double', date:'Date', uuid:'Keyword' };
enumNames = new Set();
entityNames = new Set();
for (const pkg of (model.packages || [])) {
  for (const e of (pkg.enums || [])) enumNames.add(e.name);
  for (const e of (pkg.entities || [])) entityNames.add(e.name);
}
javaTypeOf = function (t) {
  if (Object.prototype.hasOwnProperty.call(javaPrim, t)) {
    const fq = javaPrim[t]; const dot = fq.lastIndexOf('.');
    return dot >= 0 ? fq.slice(dot + 1) : fq;
  }
  return entityNames.has(t) ? 'UUID' : 'String';
};
esTypeOf = function (t) {
  if (Object.prototype.hasOwnProperty.call(esField, t)) return esField[t];
  return 'Keyword';
};

fields = (attributes || []).map(function (a) {
  return {
    name: a.name,
    camel: camelCase(a.name),
    pascal: pascalCase(a.name),
    primaryKey: !!a.primaryKey,
    javaType: javaTypeOf(a.type),
    esType: esTypeOf(a.type),
    multiValue: !!a.multiValue,
  };
});

const importSet = new Set([
  'org.springframework.data.annotation.Id',
  'org.springframework.data.elasticsearch.annotations.Document',
  'org.springframework.data.elasticsearch.annotations.Field',
  'org.springframework.data.elasticsearch.annotations.FieldType'
]);
for (const f of fields) {
  if (f.javaType === 'UUID') importSet.add('java.util.UUID');
  if (f.javaType === 'LocalDateTime') importSet.add('java.time.LocalDateTime');
  if (f.javaType === 'BigDecimal') importSet.add('java.math.BigDecimal');
  if (f.multiValue) importSet.add('java.util.List');
}
importLines = Array.from(importSet).sort().map(function (i) { return 'import ' + i + ';'; }).join('\n');

fieldDecls = fields.map(function (f) {
  const lines = [];
  if (f.primaryKey) lines.push('  @Id');
  lines.push('  @Field(type = FieldType.' + f.esType + ')');
  const javaType = f.multiValue ? ('List<' + f.javaType + '>') : f.javaType;
  lines.push('  private ' + javaType + ' ' + f.camel + ';');
  return lines.join('\n');
}).join('\n\n');

accessors = fields.map(function (f) {
  const javaType = f.multiValue ? ('List<' + f.javaType + '>') : f.javaType;
  return (
    '  public ' + javaType + ' get' + f.pascal + '() { return ' + f.camel + '; }\n' +
    '  public void set' + f.pascal + '(' + javaType + ' ' + f.camel + ') { this.' + f.camel + ' = ' + f.camel + '; }'
  );
}).join('\n\n');

indexName = snakeCase(name);

package com.example.blog.search;

{{{importLines}}}

@Document(indexName = "{{indexName}}")
public class {{pascalCase name}}Document {

{{{fieldDecls}}}

  public {{pascalCase name}}Document() {}

{{{accessors}}}
}
